if __name__ == "__main__":
    allb, allp, alll = e1.books + books, e1.places + places, e1.lines + lines
    ids = [x["id"] for x in allp]
    assert len(ids) == len(set(ids)), [i for i in ids if ids.count(i) > 1]
    lids = [x["id"] for x in alll]
    assert len(lids) == len(set(lids)), [i for i in lids if lids.count(i) > 1]
    bids = {x["id"] for x in allb} | {"fr-sun-also-rises"}
    assert len(allb) == len({x["id"] for x in allb})
    for l in alll:
        for p in l["place_ids"]: assert p in ids, (l["id"], p)
        assert l["book_id"] in bids, l["id"]
    for x in allp:
        for bk in x.get("book_ids", []): assert bk in bids, (x["id"], bk)
    e1.write("books", allb, "2026-11-17")
    e1.write("places", allp, "2026-11-17")
    e1.write("lines", alll, "2026-11-17")
    print(len(allb), "books,", len(allp), "places,", len(alll), "lines")
